      identity: [{ method: "GET", path: "/v0/tenants/me/api-keys" }, { method: "POST", path: "/v0/tenants/me/api-keys" }, { method: "GET", path: "/v0/tenants/me/api-keys/:keyId" }, { method: "DELETE", path: "/v0/tenants/me/api-keys/:keyId" }, { method: "GET", path: "/v0/tenants/me/users" }, { method: "POST", path: "/v0/tenants/me/users" }, { method: "GET", path: "/v0/tenants/me/users/:userId" }, { method: "PATCH", path: "/v0/tenants/me/users/:userId" }, { method: "POST", path: "/v0/tenants/me/users/:userId/disable" }, { method: "POST", path: "/v0/tenants/me/users/:userId/enable" }, { method: "POST", path: "/v0/auth/login" }, { method: "GET", path: "/v0/auth/me" }, { method: "PATCH", path: "/v0/auth/me" }, { method: "POST", path: "/v0/auth/refresh" }, { method: "POST", path: "/v0/auth/logout" }],
      initiatives: [{ method: "GET", path: "/v0/tenants/me/initiatives" }, { method: "POST", path: "/v0/tenants/me/initiatives" }, { method: "GET", path: "/v0/tenants/me/initiatives/:initiativeId" }, { method: "PUT", path: "/v0/tenants/me/initiatives/:initiativeId/sourcing" }, { method: "PUT", path: "/v0/tenants/me/initiatives/:initiativeId/kill" }, { method: "PUT", path: "/v0/tenants/me/initiatives/:initiativeId/scale" }],
      packs: [{ method: "GET", path: "/v0/tenants/me/packs" }, { method: "POST", path: "/v0/tenants/me/packs" }, { method: "GET", path: "/v0/tenants/me/packs/:packId" }, { method: "POST", path: "/v0/tenants/me/packs/:packId/publish" }],
      partners: [{ method: "GET", path: "/v0/tenants/me/partners" }, { method: "POST", path: "/v0/tenants/me/partners" }, { method: "GET", path: "/v0/tenants/me/partners/:partnerId" }, { method: "PUT", path: "/v0/tenants/me/partners/:partnerId/criticality" }],
      sensing: [{ method: "GET", path: "/v0/tenants/me/sensing/signals" }, { method: "POST", path: "/v0/tenants/me/sensing/signals" }, { method: "GET", path: "/v0/tenants/me/sensing/signals/:signalId" }, { method: "PUT", path: "/v0/tenants/me/sensing/signals/:signalId/hype-assessment" }, { method: "POST", path: "/v0/tenants/me/sensing/signals/:signalId/decision" }],
      talent: [{ method: "GET", path: "/v0/tenants/me/talent/gaps" }, { method: "POST", path: "/v0/tenants/me/talent/gaps" }, { method: "GET", path: "/v0/tenants/me/talent/gaps/:gapId" }, { method: "PATCH", path: "/v0/tenants/me/talent/gaps/:gapId" }],
